function systemFor(name: string, index: number) {
  if (index <= 9) return "Neurologi & psikiatri";
  if (index <= 21) return "Mata";
  if (index <= 31) return "THT";
  if (index <= 41) return "Respirasi";
  if (index === 42) return "Kardiovaskular";
  if (index <= 62) return "Gastrointestinal";
  if (index <= 68) return "Ginjal & urologi";
  if (index <= 80) return "Reproduksi & obstetri";
  if (index <= 91) return "Endokrin & metabolik";
  if (index <= 96) return "Hematologi & infeksi sistemik";
  if (index <= 97) return "Muskuloskeletal";
  if (index <= 143) return "Integumen";
  return "Forensik & medikolegal";
}

